     1	//! Report account balances from a ledger file.
     2	
     3	use std::collections::HashMap;
     4	use std::env;
     5	use std::fs;
     6	
     7	fn to_cents(amount: &str) -> i64 {
     8	    let whole_only: i64 = amount.split('.').next().unwrap_or("0").parse().unwrap_or(0);
     9	    whole_only * 100
    10	}
    11	
    12	fn format_cents(cents: i64) -> String {
    13	    let sign = if cents < 0 { "-" } else { "" };
    14	    let cents = cents.abs();
    15	    format!("{}{}.{:02}", sign, cents / 100, cents % 100)
    16	}
    17	
    18	fn by_account(entry: &(String, i64)) -> String {
    19	    entry.0.clone()
    20	}
    21	
    22	fn read_ledger(path: &str) -> String {
    23	    fs::read_to_string(path).expect("a readable ledger")
    24	}
    25	
    26	fn main() {
    27	    let path = env::args().nth(1).expect("a ledger path");
    28	    let text = read_ledger(&path);
    29	    let lines: Vec<&str> = text.trim_end_matches('\n').split('\n').collect();
    30	    let n: i64 = lines[0].split(' ').nth(1).unwrap().parse().unwrap();
    31	    if n == 0 {
    32	        return;
    33	    }
    34	
    35	    let debit_sign = 1;
    36	    let mut balances: HashMap<String, i64> = HashMap::new();
    37	    let mut skipped = 0;
    38	    for index in 0..n - 1 {
    39	        let fields: Vec<&str> = lines[1 + index as usize].split(' ').collect();
    40	        let (account, kind, amount) = (fields[0], fields[1], fields[2]);
    41	        let amount_cents = to_cents(amount);
    42	        let mut signed = amount_cents;
    43	        if kind == "debit" {
    44	            signed = amount_cents * debit_sign;
    45	        } else if kind != "credit" {
    46	            skipped += 1;
    47	            continue;
    48	        }
    49	        *balances.entry(account.to_string()).or_insert(0) += signed;
    50	    }
    51	
    52	    let mut entries: Vec<(String, i64)> = balances.into_iter().collect();
    53	    entries.sort_by_key(by_account);
    54	    let mut total = 0;
    55	    for (account, balance) in &entries {
    56	        println!("{} {}", account, format_cents(*balance));
    57	        total += balance;
    58	    }
    59	    println!("TOTAL {}", format_cents(total));
    60	    if skipped > 0 {
    61	        eprintln!("skipped {}", skipped);
    62	    }
    63	}
