input.command:
python3 -I - <<'EOF'
p='src/main.rs'
s=open(p).read()
i=s.index('fn to_cents'); j=s.index('fn read_ledger')
s=s[:i]+'''fn to_cents(amount: &str) -> i128 {
    let (whole, frac) = amount.split_once('.').unwrap_or((amount, "0"));
    let whole: i128 = whole.parse().unwrap_or(0);
    let mut frac_digits = frac.chars().take(2).collect::<String>();
    while frac_digits.len() < 2 {
        frac_digits.push('0');
    }
    let frac: i128 = frac_digits.parse().unwrap_or(0);
    whole * 100 + frac
}

fn format_cents(cents: i128) -> String {
    let sign = if cents < 0 { "-" } else { "" };
    let cents = cents.abs();
    format!("{}{}.{:02}", sign, cents / 100, cents % 100)
}

'''+s[j:]
i=s.index('fn main')
s=s[:i]+'''fn main() {
    let path = env::args().nth(1).expect("a ledger path");
    let text = read_ledger(&path);
    let mut lines = text.lines();
    let n: usize = lines
        .next()
        .and_then(|header| header.split_whitespace().nth(1))
        .and_then(|count| count.parse().ok())
        .unwrap_or(0);

    let mut balances: HashMap<String, i128> = HashMap::new();
    for (index, line) in lines.take(n).enumerate() {
        let fields: Vec<&str> = line.split_whitespace().collect();
        if fields.len() < 3 {
            continue;
        }
        let (account, kind, amount) = (fields[0], fields[1], fields[2]);
        let cents = to_cents(amount);
        let signed = match kind {
            "debit" => -cents,
            "credit" => cents,
            _ => {
                println!("ERROR line {}", index + 1);
                return;
            }
        };
        *balances.entry(account.to_string()).or_insert(0) += signed;
    }

    let mut entries: Vec<(String, i128)> = balances.into_iter().collect();
    entries.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.as_bytes().cmp(b.0.as_bytes())));
    let mut total = 0;
    for (account, balance) in &entries {
        println!("{} {}", account, format_cents(*balance));
        total += balance;
    }
    println!("TOTAL {}", format_cents(total));
}
'''
open(p,'w').write(s)
